class BadEqualsConsistency(id: String, name: String) {
    private val id = id
    private val name = name // bad

    override fun equals(other: Any?): Boolean {
        return other is BadEqualsConsistency && id == other.id
    }

    override fun hashCode(): Int {
        return 31 * id.hashCode() + name.hashCode()
    }
}

class GoodEqualsConsistency(id: String, name: String) {
    private val id = id
    private val name = name

    override fun equals(other: Any?): Boolean {
        return other is GoodEqualsConsistency && id == other.id && name == other.name
    }

    override fun hashCode(): Int {
        return 31 * id.hashCode() + name.hashCode()
    }
}
